// Ticket-Objekt kommt aus dem Zweig "Nur relevante Tickets" (True), die Artikel-Liste aus "Ticket-Artikel laden".
const ticket = $('Nur relevante Tickets').item.json;
const articles = $input.first().json || [];

function stripHtml(html) {
  return String(html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

const verlauf = articles
  .map((a) => `[${a.from || 'unbekannt'}]: ${stripHtml(a.body)}`)
  .join('\n\n');

const prompt = [
  'Du bist Support-Assistent und entwirfst NUR einen Antwortvorschlag -- er wird von einem Menschen geprueft, bevor er verschickt wird.',
  `Ticket-Titel: ${ticket.title}`,
  '',
  'Bisheriger Verlauf:',
  verlauf,
  '',
  'Formuliere einen hoeflichen, knappen Antwortentwurf auf Deutsch. Wenn dir Informationen fehlen, formuliere stattdessen Rueckfragen statt zu raten.',
].join('\n');

return [{ json: { ticket, prompt } }];

// Ollama /api/generate liefert mit stream:false ein einzelnes JSON-Objekt
// mit dem fertigen Text im Feld "response" (siehe https://github.com/ollama/ollama/blob/main/docs/api.md#generate-a-completion).
const ticket = $('LLM-Prompt bauen').item.json.ticket;
const entwurf = $json.response || JSON.stringify($json);

return [{ json: { ticket, entwurf } }];

// Laeuft IMMER genau einmal, unabhaengig davon, ob 0 oder mehrere Tickets
// gefunden/verarbeitet wurden -- "Run Once for All Items" ignoriert die
// tatsaechliche Item-Anzahl. Zusaetzlich direkt vom Trigger-Node gespeist
// (siehe connections unten), damit dieser Node auch dann feuert, wenn der
// Ticket-Zweig oben komplett leer durchlaeuft. Der Haupt-Workflow verlaesst
// sich auf genau dieses eine Rueckgabe-Item, um zuverlaessig weiterzulaufen
// (Ollama wieder herunterskalieren).
return [{ json: { status: 'done', verarbeiteteTickets: $input.all().length } }];
